"""Configure the HTML and REST adapters generated by a registration."""

from __future__ import annotations

from collections.abc import Sequence
from typing import Any

import sqlalchemy as sa

from obox._async import invoke
from obox._auth import has_permission
from obox.api import ModelApi
from obox.core.exceptions import PermissionDenied
from obox.db._identity import _model_label
from obox.forms import ModelForm, modelform_factory
from obox.resources import Resource
from obox.views.generic import CreateView, DeleteView, DetailView, ListView, UpdateView


def _flatten(fields: Any) -> list[str]:
    return [
        name
        for item in fields
        for name in (_flatten(item) if isinstance(item, (list, tuple)) else [item])
    ]


class ModelBuilder:
    slug: str | None = None
    api_class: type[ModelApi[Any]] = ModelApi
    list_view: type[ListView] = ListView
    detail_view: type[DetailView] = DetailView
    create_view: type[CreateView] = CreateView
    update_view: type[UpdateView] = UpdateView
    delete_view: type[DeleteView] = DeleteView
    form: type[ModelForm] = ModelForm
    fields: Any = None
    fieldsets: Any = None
    exclude: Any = None
    readonly_fields: Sequence[str] = ()
    list_display: Sequence[Any] = ("__str__",)
    list_display_links: Any = ()
    list_filter: Sequence[str] = ()
    search_fields: Sequence[str] = ()
    ordering: Sequence[str] = ()
    list_per_page = 100
    actions: Any = ()
    change_list_template: str | None = None
    add_form_template: str | None = None
    change_form_template: str | None = None
    delete_confirmation_template: str | None = None
    inlines: Sequence[type[InlineModelAdmin]] = ()

    def __init__(self, model: type[Any], resource: Resource[Any] | None = None) -> None:
        self.model, self.resource = model, resource
        self.app_label, self.model_name = _model_label(model)

    def get_queryset(self, request: Any) -> Any:
        query = sa.select(self.model)
        ordering = self.get_ordering(request)
        if ordering:
            query = query.order_by(
                *(
                    getattr(self.model, name.lstrip("-")).desc()
                    if name.startswith("-")
                    else getattr(self.model, name)
                    for name in ordering
                )
            )
        return query

    def get_ordering(self, request: Any) -> Any:
        return self.ordering

    def get_list_display(self, request: Any) -> Any:
        if self.resource is not None:
            if self.list_display == ("__str__",):
                return self.resource.readable
            return tuple(
                name
                for name in self.list_display
                if callable(name)
                or name not in self.resource.specs
                or name in self.resource.readable
            )
        return self.list_display

    def get_list_display_links(self, request: Any, list_display: Any) -> Any:
        if self.list_display_links is None or self.list_display_links:
            return self.list_display_links
        return list_display[:1]

    def get_list_filter(self, request: Any) -> Any:
        if self.resource is None:
            return self.list_filter
        return tuple(name for name in self.list_filter if name in self.resource.readable)

    def get_search_fields(self, request: Any) -> Any:
        return self.search_fields

    def get_readonly_fields(self, request: Any, obj: Any = None) -> Any:
        return self.readonly_fields

    def get_fields(self, request: Any, obj: Any = None) -> Any:
        if self.fields is not None:
            return self.fields
        if self.fieldsets is not None:
            return _flatten([options["fields"] for _, options in self.fieldsets])
        meta = getattr(self.form, "Meta", None)
        defines_fields = (
            getattr(meta, "fields", None) is not None or getattr(meta, "exclude", None) is not None
        )
        if self.resource is not None and not defines_fields:
            return self.resource.writable
        cls = modelform_factory(
            self.model,
            self.form,
            fields=None if defines_fields else "__all__",
            exclude=[
                *(self.get_exclude(request, obj) or getattr(meta, "exclude", ()) or ()),
                *self.get_readonly_fields(request, obj),
            ],
        )
        return [*cls.base_fields, *self.get_readonly_fields(request, obj)]

    def get_fieldsets(self, request: Any, obj: Any = None) -> Any:
        return self.fieldsets or [(None, {"fields": self.get_fields(request, obj)})]

    def get_exclude(self, request: Any, obj: Any = None) -> Any:
        return self.exclude

    def get_form(
        self, request: Any, obj: Any = None, change: bool = False, **kwargs: Any
    ) -> type[ModelForm]:
        fields = _flatten(kwargs.pop("fields", self.get_fields(request, obj)))
        if self.resource is not None:
            fields = [name for name in fields if name in self.resource.readable]
        readonly = tuple(self.get_readonly_fields(request, obj))
        excluded = self.get_exclude(request, obj)
        exclude = [
            *(
                excluded
                if excluded is not None
                else (getattr(getattr(self.form, "Meta", None), "exclude", ()) or ())
            ),
            *readonly,
        ]
        if self.resource is not None:
            exclude.extend(name for name in fields if name not in self.resource.writable)
        if change and hasattr(request, "user") and not self.has_change_permission(request, obj):
            exclude.extend(fields)
        form = kwargs.pop("form", self.form)
        form = type(
            form.__name__,
            (form,),
            dict.fromkeys(name for name in readonly if name in form.declared_fields),
        )
        return modelform_factory(
            self.model,
            form,
            fields=[name for name in fields if name not in exclude],
            exclude=exclude,
            **kwargs,
        )

    def get_search_results(self, request: Any, queryset: Any, search_term: str) -> tuple[Any, bool]:
        for word in search_term.split():
            predicates = []
            for name in self.get_search_fields(request):
                prefix = name[:1]
                field = name[1:] if prefix in ("^", "=") else name
                if self.resource is not None and field not in self.resource.readable:
                    continue
                column = getattr(self.model, field)
                predicates.append(
                    column.istartswith(word, autoescape=True)
                    if prefix == "^"
                    else sa.func.lower(column) == word.lower()
                    if prefix == "="
                    else column.icontains(word, autoescape=True)
                )
            if predicates:
                queryset = queryset.where(sa.or_(*predicates))
        return queryset, False

    async def save_model(self, request: Any, obj: Any, form: ModelForm, change: bool) -> None:
        """Run additional HTML behavior after the shared Resource saves the record."""

    async def save_related(
        self, request: Any, form: ModelForm, formsets: Any, change: bool
    ) -> None:
        await form.save_m2m()
        for formset in formsets:
            await self.save_formset(request, form, formset, change)

    async def save_formset(self, request: Any, form: ModelForm, formset: Any, change: bool) -> None:
        await formset.save()

    def get_inlines(self, request: Any, obj: Any = None) -> Any:
        return self.inlines

    def get_inline_instances(self, request: Any, obj: Any = None) -> Any:
        return [inline(self.model) for inline in self.get_inlines(request, obj)]

    def get_formsets_with_inlines(self, request: Any, obj: Any = None) -> Any:
        return (
            (inline.get_formset(request, obj), inline)
            for inline in self.get_inline_instances(request, obj)
        )

    def _permission(self, request: Any, action: str) -> bool:
        return has_permission(request.user, f"{self.app_label}.{action}_{self.model_name}")

    def has_add_permission(self, request: Any) -> bool:
        return self._permission(request, "add")

    def has_change_permission(self, request: Any, obj: Any = None) -> bool:
        return self._permission(request, "change")

    def has_delete_permission(self, request: Any, obj: Any = None) -> bool:
        return self._permission(request, "delete")

    def has_view_permission(self, request: Any, obj: Any = None) -> bool:
        return self._permission(request, "view")

    def get_model_perms(self, request: Any) -> dict[str, bool]:
        return {
            name: bool(getattr(self, f"has_{name}_permission")(request))
            for name in ("add", "change", "delete", "view")
        }

    def get_actions(self, request: Any) -> dict[str, Any]:
        if self.actions is None:
            return {}
        from obox.builder.routes import delete_selected

        result = {"delete_selected": delete_selected}
        for action in self.actions:
            method = getattr(type(self), action) if isinstance(action, str) else action
            result[method.__name__] = method
        allowed = {}
        for name, method in result.items():
            permissions = getattr(method, "allowed_permissions", ("change",))
            if any(
                getattr(self, f"has_{permission}_permission")(request) for permission in permissions
            ):
                allowed[name] = (
                    method,
                    name,
                    getattr(method, "short_description", name.replace("_", " ").capitalize()),
                )
        return allowed


class InlineModelAdmin(ModelBuilder):
    model: type[Any]
    fk_name: str | None = None
    formset: Any = None
    extra = 3
    min_num = 0
    max_num: int | None = None
    can_delete = True
    template = "obox/builder/stacked.html"

    def __init__(self, parent_model: type[Any]) -> None:
        super().__init__(self.model)
        self.parent_model = parent_model

    def get_extra(self, request: Any, obj: Any = None, **kwargs: Any) -> int:
        return self.extra

    def get_min_num(self, request: Any, obj: Any = None, **kwargs: Any) -> int:
        return self.min_num

    def get_max_num(self, request: Any, obj: Any = None, **kwargs: Any) -> int | None:
        return self.max_num

    def get_formset(self, request: Any, obj: Any = None, **kwargs: Any) -> Any:
        from obox.forms import BaseInlineFormSet, inlineformset_factory

        inline = self
        base = self.formset or BaseInlineFormSet

        class PermissionFormSet(base):  # type: ignore[misc, valid-type]
            async def save_new(self, form: Any, commit: bool = True) -> Any:
                if not await invoke(inline.has_add_permission, request):
                    raise PermissionDenied()
                return await super().save_new(form, commit)

            async def save_existing(self, form: Any, instance: Any, commit: bool = True) -> Any:
                if not await invoke(inline.has_change_permission, request, instance):
                    raise PermissionDenied()
                return await super().save_existing(form, instance, commit)

            async def delete_existing(self, instance: Any, commit: bool = True) -> None:
                if not await invoke(inline.has_delete_permission, request, instance):
                    raise PermissionDenied()
                await super().delete_existing(instance, commit)

        return inlineformset_factory(
            self.parent_model,
            self.model,
            self.form,
            formset=PermissionFormSet,
            fk_name=self.fk_name,
            fields=self.get_fields(request, obj),
            exclude=self.get_exclude(request, obj),
            extra=self.get_extra(request, obj),
            min_num=self.get_min_num(request, obj),
            max_num=self.get_max_num(request, obj),
            can_delete=self.can_delete,
            **kwargs,
        )


class TabularInline(InlineModelAdmin):
    template = "obox/builder/tabular.html"


class StackedInline(InlineModelAdmin):
    pass
